target='.......((.((.((....)).((...))...)))).((.((.((....)).((...))...)))).((.((.((....)).((...))...)))).......'
n=len(target)
pairs=set(); stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs.add((j,i))
unpaired=set(range(n))-set([i for p in pairs for i in p])

def fold_ss(s):
    fc=RNA.fold_compound(s); ss,e=fc.mfe(); return ss,e
def bp_dist(s):
    ss,e=fold_ss(s)
    set_ss=set(); st=[]
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); set_ss.add((j,i))
    return len(pairs-set_ss)+len(set_ss-pairs), ss, e

